// Shared background renderer. Uses the site's existing canvas lifecycle and controls.
(()=>{
const CONFIG={colors:{cream:'#FFE3D6',pink:'#FF4D9A',magenta:'#E6007E',orange:'#FFB347'},blur:{back:48,front:7,line:5},steps:12,drift:35,breathing:.05};
const back=document.createElement('canvas'),front=document.createElement('canvas'),grain=document.createElement('canvas'),bc=back.getContext('2d'),fc=front.getContext('2d'),gc=grain.getContext('2d');let width=0,height=0;const seed=Math.random()*100;
const smooth=t=>{t=Math.max(0,Math.min(1,t));return t*t*(3-2*t)},hash=(x,y)=>{const v=Math.sin(x*127.1+y*311.7)*43758.5453;return v-Math.floor(v)},noise=(x,y)=>{const a=Math.floor(x),b=Math.floor(y),u=smooth(x-a),v=smooth(y-b),mix=(a,b,t)=>a+(b-a)*t;return mix(mix(hash(a,b),hash(a+1,b),u),mix(hash(a,b+1),hash(a+1,b+1),u),v)},rgb=c=>{const n=parseInt(c.replace('#',''),16);return[n>>16&255,n>>8&255,n&255]},rgba=(c,a)=>'rgba('+rgb(c).join(',')+','+a+')';
function easedGradientStops(g,color){for(let i=0;i<CONFIG.steps;i++){const t=i/(CONFIG.steps-1);g.addColorStop(t,rgba(color,1-smooth(t)))}}
function drawGlow(c,x,y,r){const g=c.createRadialGradient(x,y,0,x,y,r);easedGradientStops(g,'#ffffff');c.save();c.globalCompositeOperation='screen';c.fillStyle=g;c.fillRect(x-r,y-r,r*2,r*2);c.restore()}
function drawOrb(c,x,y,r,o){const g=c.createRadialGradient(x-r*.28,y-r*.22,0,x,y,r),colors=[o.peach||CONFIG.colors.orange,o.pink||CONFIG.colors.pink,CONFIG.colors.magenta];for(let i=0;i<CONFIG.steps;i++){const t=i/(CONFIG.steps-1),part=t<.48?0:1,u=smooth(part?(t-.48)/.52:t/.48),a=rgb(colors[part]),b=rgb(colors[part+1]),color=a.map((n,j)=>Math.round(n+(b[j]-n)*u));g.addColorStop(t,'rgba('+color.join(',')+','+(1-smooth((t-.22)/.78))+')')}c.fillStyle=g;c.fillRect(x-r,y-r,r*2,r*2)}
function drawSparkle(c,x,y,rx,ry){c.save();c.translate(x,y);const g=c.createLinearGradient(0,-ry,0,ry);for(let i=0;i<CONFIG.steps;i++){const t=i/(CONFIG.steps-1),d=Math.abs(t-.5)*2,a=rgb(d<.45?'#fff4e8':CONFIG.colors.magenta),b=rgb(d<.45?CONFIG.colors.magenta:CONFIG.colors.orange),u=smooth(d<.45?d/.45:(d-.45)/.55),color=a.map((v,j)=>Math.round(v+(b[j]-v)*u));g.addColorStop(t,'rgba('+color.join(',')+',.92)')}c.beginPath();c.moveTo(0,-ry);c.bezierCurveTo(rx*.08,-ry*.15,rx*.15,-ry*.08,rx,0);c.bezierCurveTo(rx*.15,ry*.08,rx*.08,ry*.15,0,ry);c.bezierCurveTo(-rx*.08,ry*.15,-rx*.15,ry*.08,-rx,0);c.bezierCurveTo(-rx*.15,-ry*.08,-rx*.08,-ry*.15,0,-ry);c.fillStyle=g;c.fill();drawGlow(c,0,0,rx*.4);c.restore()}
function resize(w,h){if(width===w&&height===h)return;width=w;height=h;for(const c of[back,front,grain]){c.width=w;c.height=h}const pixels=gc.createImageData(w,h);for(let i=0;i<pixels.data.length;i+=4){const v=Math.random()*255;pixels.data[i]=pixels.data[i+1]=pixels.data[i+2]=v;pixels.data[i+3]=15}gc.putImageData(pixels,0,0)}
function render(c,now,o,w,h){resize(w,h);const t=now*.00012*(o.speed??1),drift=Math.min(w,h)*.045,positions=[[-.04,.16,.46],[1,.72,.48],[.43,1.08,.42]];bc.clearRect(0,0,w,h);bc.fillStyle=o.cream||CONFIG.colors.cream;bc.fillRect(0,0,w,h);fc.clearRect(0,0,w,h);positions.forEach(([x,y,r],i)=>{const dx=(noise(seed+i*7,t)-.5)*drift*2,dy=(noise(seed+40+i*9,t)-.5)*drift*2;drawOrb(bc,x*w+dx,y*h+dy,w*r*(1+Math.sin(t+i)*CONFIG.breathing),o)});drawGlow(bc,w*.6,h*.28,w*.23);for(let i=0;i<5;i++){const x=(.15+(i*.193)% .76)*w+(noise(seed+i,t)-.5)*drift,y=(.17+(i*.271)%.7)*h+(noise(seed+20+i,t)-.5)*drift,r=w*(.038+(i%3)*.015);drawSparkle(fc,x,y,r,r*(1.3+(i%2)*.55))}
c.clearRect(0,0,w,h);c.fillStyle=o.cream||CONFIG.colors.cream;c.fillRect(0,0,w,h);c.save();if('filter'in c){c.filter='blur('+CONFIG.blur.back*.5+'px)';c.drawImage(back,0,0)}else{c.globalAlpha=1/24;for(let i=0;i<24;i++){const angle=i*2.39996,r=Math.sqrt(i/24)*w*.04;c.drawImage(back,Math.cos(angle)*r,Math.sin(angle)*r)}};c.restore();c.save();if('filter'in c)c.filter='blur('+CONFIG.blur.front*.5+'px)';c.drawImage(front,0,0);c.restore();c.save();c.globalCompositeOperation='screen';for(let i=0;i<4;i++){const path=()=>{c.beginPath();for(let x=-20;x<w+20;x+=4){const y=h*(.12+i*.24)+(noise(seed+i*8+x/w*2,t*.7)-.5)*h*.65+(noise(seed+90+i+x/w*5,t)-.5)*h*.08;x===-20?c.moveTo(x,y):c.lineTo(x,y)}c.stroke()};c.strokeStyle='#fff4e8';c.lineCap='round';c.globalAlpha=.35;c.lineWidth=6;if('filter'in c)c.filter='blur(4px)';path();c.filter='none';c.globalAlpha=.85;c.lineWidth=1.3;path()}c.restore();if(o.grain>0){c.save();c.globalCompositeOperation='overlay';c.globalAlpha=Math.min(1,o.grain);c.drawImage(grain,0,0);c.restore()}}
window.glowBackdrop={render,CONFIG};
})();
